"use client";

/**
 * The last error boundary: it catches what `app/error.tsx` cannot — an error thrown by the root layout itself.
 * It replaces the root layout, so it renders its own <html> and <body>, and it cannot rely on the app's providers,
 * fonts, theme or next-intl messages: keep it plain and self-contained. Its copy is the one place outside the
 * message files: add the app's other locales to COPY below, and the browser's language picks one after mount.
 *
 * Generated by `design-md-to-app`. The `errors` level of `module-add observability` adds
 * `Sentry.captureException(error)` in the effect below, so the error reaches the tracker with its release.
 */
import { useEffect, useState } from "react";

const COPY = {
  en: {
    title: "Something went wrong",
    body: "The page could not load. Try again; if it keeps happening, quote this code to support:",
    retry: "Try again",
  },
  it: {
    title: "Qualcosa non ha funzionato",
    body: "Non riesco a caricare la pagina. Riprova; se succede ancora, comunica questo codice all'assistenza:",
    retry: "Riprova",
  },
} as const;
type Locale = keyof typeof COPY;

export default function GlobalError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  // English on the server and the first paint, then the browser's language: no hydration mismatch
  const [locale, setLocale] = useState<Locale>("en");
  useEffect(() => {
    const lang = navigator.language.slice(0, 2);
    if (lang in COPY) setLocale(lang as Locale);
  }, []);
  const t = COPY[locale];

  useEffect(() => {
    // module-add observability (errors) replaces this line with Sentry.captureException(error).
    console.error("[global-error.tsx]", error);
  }, [error]);

  return (
    <html lang={locale}>
      <body style={{ fontFamily: "system-ui, sans-serif", display: "grid", placeItems: "center", minHeight: "100vh", margin: 0 }}>
        <main style={{ maxWidth: 420, textAlign: "center", padding: 24 }}>
          <h1 style={{ fontSize: 20, margin: "0 0 8px" }}>{t.title}</h1>
          <p style={{ margin: "0 0 16px", opacity: 0.7 }}>
            {t.body}
            {error.digest ? <code> {error.digest}</code> : null}
          </p>
          <button type="button" onClick={() => reset()} style={{ padding: "8px 16px", cursor: "pointer" }}>
            {t.retry}
          </button>
        </main>
      </body>
    </html>
  );
}
